export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const FREE_TYPES = 3;
const SCORE_WITHIN_FREE_TYPES = 2;
const BONUS_PER_EXTRA_TYPE = 2;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countNonSphinxTypes = (army: Card[]): number =>
  new Set(army.filter((card) => card.monster !== SPHINX).map((card) => card.monster))
    .size;

// Beyond the free allowance the score runs 3, 5, 7, … — each extra type adds
// BONUS_PER_EXTRA_TYPE, but the first extra type only lifts the score from 2 to
// 3, so the run starts one point below SCORE_WITHIN_FREE_TYPES + bonus.
const scoreBeyondFreeTypes = (types: number): number =>
  SCORE_WITHIN_FREE_TYPES - 1 + BONUS_PER_EXTRA_TYPE * (types - FREE_TYPES);

const scoreForTypeCount = (types: number): number =>
  types > FREE_TYPES ? scoreBeyondFreeTypes(types) : SCORE_WITHIN_FREE_TYPES;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  return scoreForTypeCount(countNonSphinxTypes(army));
};

